607|		 * The postmaster already started the XLOG machinery, but we need to
608|		 * call InitXLOGAccess(), if the system isn't in hot-standby mode.
609|		 * This is handled by calling RecoveryInProgress and ignoring the
610|		 * result.
611|		 */
612|		(void) RecoveryInProgress();
613|	}
614|	else
615|	{
616|		/*
617|		 * We are either a bootstrap process or a standalone backend. Either
618|		 * way, start up the XLOG machinery, and register to have it closed
619|		 * down at exit.
620|		 *
621|		 * We don't yet have an aux-process resource owner, but StartupXLOG
622|		 * and ShutdownXLOG will need one.  Hence, create said resource owner
623|		 * (and register a callback to clean it up after ShutdownXLOG runs).
624|		 */
625|		CreateAuxProcessResourceOwner();
626|
627|		StartupXLOG();
628|		/* Release (and warn about) any buffer pins leaked in StartupXLOG */
629|		ReleaseAuxProcessResources(true);
630|		/* Reset CurrentResourceOwner to nothing for the moment */
631|		CurrentResourceOwner = NULL;
632|
633|		on_shmem_exit(ShutdownXLOG, 0);
634|	}
635|
636|	/*
637|	 * Initialize the relation cache and the system catalog caches.  Note that
638|	 * no catalog access happens here; we only set up the hashtable structure.
639|	 * We must do this before starting a transaction because transaction abort
640|	 * would try to touch these hashtables.
641|	 */
642|	RelationCacheInitialize();
643|	InitCatalogCache();
644|	InitPlanCache();
645|
646|	/* Initialize portal manager */
647|	EnablePortalManager();
648|
649|	/* Initialize stats collection --- must happen before first xact */
650|	if (!bootstrap)
651|		pgstat_initialize();
652|
653|	/* Initialize status reporting */
654|	if (!bootstrap)
655|		pgstat_beinit();
656|
657|	/*
658|	 * Load relcache entries for the shared system catalogs.  This must create
659|	 * at least entries for pg_database and catalogs used for authentication.
660|	 */
661|	RelationCacheInitializePhase2();
662|
663|	/*
664|	 * Set up process-exit callback to do pre-shutdown cleanup.  This is the
665|	 * first before_shmem_exit callback we register; thus, this will be the
666|	 * last thing we do before low-level modules like the buffer manager begin
667|	 * to close down.  We need to have this in place before we begin our first
668|	 * transaction --- if we fail during the initialization transaction, as is
669|	 * entirely possible, we need the AbortTransaction call to clean up.
670|	 */
671|	before_shmem_exit(ShutdownPostgres, 0);
672|
673|	/* The autovacuum launcher is done here */
674|	if (IsAutoVacuumLauncherProcess())
675|	{
676|		/* report this backend in the PgBackendStatus array */
677|		pgstat_bestart();
678|
679|		return;
680|	}
681|
682|	/*
683|	 * Start a new transaction here before first access to db, and get a
684|	 * snapshot.  We don't have a use for the snapshot itself, but we're
685|	 * interested in the secondary effect that it sets RecentGlobalXmin. (This
686|	 * is critical for anything that reads heap pages, because HOT may decide
687|	 * to prune them even if the process doesn't attempt to modify any
688|	 * tuples.)
689|	 *
690|	 * FIXME: This comment is inaccurate / the code buggy. A snapshot that is
691|	 * not pushed/active does not reliably prevent HOT pruning (->xmin could
692|	 * e.g. be cleared when cache invalidations are processed).
693|	 */
694|	if (!bootstrap)
695|	{
696|		/* statement_timestamp must be set for timeouts to work correctly */
697|		SetCurrentStatementStartTimestamp();
698|		StartTransactionCommand();
699|
700|		/*
701|		 * transaction_isolation will have been set to the default by the
702|		 * above.  If the default is "serializable", and we are in hot
703|		 * standby, we will fail if we don't change it to something lower.
704|		 * Fortunately, "read committed" is plenty good enough.
705|		 */
706|		XactIsoLevel = XACT_READ_COMMITTED;
707|
708|		(void) GetTransactionSnapshot();
709|	}
710|
711|	/*
712|	 * Perform client authentication if necessary, then figure out our
713|	 * postgres user ID, and see if we are a superuser.
714|	 *
715|	 * In standalone mode and in autovacuum worker processes, we use a fixed
716|	 * ID, otherwise we figure it out from the authenticated user name.
717|	 */
718|	if (bootstrap || IsAutoVacuumWorkerProcess())
719|	{
720|		InitializeSessionUserIdStandalone();
721|		am_superuser = true;
722|	}
723|	else if (!IsUnderPostmaster)
724|	{
725|		InitializeSessionUserIdStandalone();
726|		am_superuser = true;
727|		if (!ThereIsAtLeastOneRole())
728|			ereport(WARNING,
729|					(errcode(ERRCODE_UNDEFINED_OBJECT),
730|					 errmsg("no roles are defined in this database system"),
731|					 errhint("You should immediately run CREATE USER \"%s\" SUPERUSER;.",
732|							 username != NULL ? username : "postgres")));
733|	}
734|	else if (IsBackgroundWorker)
735|	{
736|		if (username == NULL && !OidIsValid(useroid))
737|		{
738|			InitializeSessionUserIdStandalone();
739|			am_superuser = true;
740|		}
741|		else
742|		{
743|			InitializeSessionUserId(username, useroid);
744|			am_superuser = superuser();
745|		}
746|	}
747|	else
748|	{
749|		/* normal multiuser case */
750|		Assert(MyProcPort != NULL);
751|		PerformAuthentication(MyProcPort);
752|		InitializeSessionUserId(username, useroid);
753|		am_superuser = superuser();
754|	}
755|
756|	/*
757|	 * If we're trying to shut down, only superusers can connect, and new
758|	 * replication connections are not allowed.
759|	 */
760|	if ((!am_superuser || am_walsender) &&
761|		MyProcPort != NULL &&
762|		MyProcPort->canAcceptConnections == CAC_SUPERUSER)
763|	{
764|		if (am_walsender)
765|			ereport(FATAL,
766|					(errcode(ERRCODE_INSUFFICIENT_PRIVILEGE),
767|					 errmsg("new replication connections are not allowed during database shutdown")));
768|		else
769|			ereport(FATAL,
770|					(errcode(ERRCODE_INSUFFICIENT_PRIVILEGE),
771|					 errmsg("must be superuser to connect during database shutdown")));
772|	}
773|
774|	/*
775|	 * Binary upgrades only allowed super-user connections
776|	 */
777|	if (IsBinaryUpgrade && !am_superuser)
778|	{
779|		ereport(FATAL,
780|				(errcode(ERRCODE_INSUFFICIENT_PRIVILEGE),
781|				 errmsg("must be superuser to connect in binary upgrade mode")));
782|	}
783|
784|	/*
785|	 * The last few connection slots are reserved for superusers.  Replication
786|	 * connections are drawn from slots reserved with max_wal_senders and not
787|	 * limited by max_connections or superuser_reserved_connections.
788|	 */
789|	if (!am_superuser && !am_walsender &&
790|		ReservedBackends > 0 &&
791|		!HaveNFreeProcs(ReservedBackends))
792|		ereport(FATAL,
793|				(errcode(ERRCODE_TOO_MANY_CONNECTIONS),
794|				 errmsg("remaining connection slots are reserved for non-replication superuser connections")));
795|
796|	/* Check replication permissions needed for walsender processes. */
797|	if (am_walsender)
798|	{
799|		Assert(!bootstrap);
800|
801|		if (!superuser() && !has_rolreplication(GetUserId()))
802|			ereport(FATAL,
803|					(errcode(ERRCODE_INSUFFICIENT_PRIVILEGE),
804|					 errmsg("must be superuser or replication role to start walsender")));
805|	}
806|
807|	/*
808|	 * If this is a plain walsender only supporting physical replication, we
809|	 * don't want to connect to any particular database. Just finish the
810|	 * backend startup by processing any options from the startup packet, and
811|	 * we're done.
812|	 */
813|	if (am_walsender && !am_db_walsender)
814|	{
815|		/* process any options passed in the startup packet */
816|		if (MyProcPort != NULL)
817|			process_startup_options(MyProcPort, am_superuser);
818|
819|		/* Apply PostAuthDelay as soon as we've read all options */
820|		if (PostAuthDelay > 0)
821|			pg_usleep(PostAuthDelay * 1000000L);
822|
823|		/* initialize client encoding */
824|		InitializeClientEncoding();
825|
826|		/* report this backend in the PgBackendStatus array */
827|		pgstat_bestart();
828|
829|		/* close the transaction we started above */
830|		CommitTransactionCommand();
831|
832|		return;
833|	}
834|
835|	/*
836|	 * Set up the global variables holding database id and default tablespace.
837|	 * But note we won't actually try to touch the database just yet.
838|	 *
839|	 * We take a shortcut in the bootstrap case, otherwise we have to look up
840|	 * the db's entry in pg_database.
841|	 */
842|	if (bootstrap)
843|	{
844|		MyDatabaseId = TemplateDbOid;
845|		MyDatabaseTableSpace = DEFAULTTABLESPACE_OID;
846|	}
847|	else if (in_dbname != NULL)
848|	{
849|		HeapTuple	tuple;
850|		Form_pg_database dbform;
851|
852|		tuple = GetDatabaseTuple(in_dbname);
853|		if (!HeapTupleIsValid(tuple))
854|			ereport(FATAL,
855|					(errcode(ERRCODE_UNDEFINED_DATABASE),
856|					 errmsg("database \"%s\" does not exist", in_dbname)));
857|		dbform = (Form_pg_database) GETSTRUCT(tuple);
858|		MyDatabaseId = dbform->oid;
859|		MyDatabaseTableSpace = dbform->dattablespace;
860|		/* take database name from the caller, just for paranoia */
861|		strlcpy(dbname, in_dbname, sizeof(dbname));
862|	}
863|	else if (OidIsValid(dboid))
864|	{
865|		/* caller specified database by OID */
866|		HeapTuple	tuple;
867|		Form_pg_database dbform;
868|
869|		tuple = GetDatabaseTupleByOid(dboid);
870|		if (!HeapTupleIsValid(tuple))
871|			ereport(FATAL,
872|					(errcode(ERRCODE_UNDEFINED_DATABASE),
873|					 errmsg("database %u does not exist", dboid)));
874|		dbform = (Form_pg_database) GETSTRUCT(tuple);
875|		MyDatabaseId = dbform->oid;
876|		MyDatabaseTableSpace = dbform->dattablespace;
877|		Assert(MyDatabaseId == dboid);
878|		strlcpy(dbname, NameStr(dbform->datname), sizeof(dbname));
879|		/* pass the database name back to the caller */
880|		if (out_dbname)
881|			strcpy(out_dbname, dbname);
882|	}
883|	else
884|	{
885|		/*
886|		 * If this is a background worker not bound to any particular
887|		 * database, we're done now.  Everything that follows only makes sense
888|		 * if we are bound to a specific database.  We do need to close the
889|		 * transaction we started before returning.
890|		 */
891|		if (!bootstrap)
892|		{
893|			pgstat_bestart();
894|			CommitTransactionCommand();
895|		}
896|		return;
897|	}
898|
899|	/*
900|	 * Now, take a writer's lock on the database we are trying to connect to.
901|	 * If there is a concurrently running DROP DATABASE on that database, this
902|	 * will block us until it finishes (and has committed its update of
903|	 * pg_database).
904|	 *
905|	 * Note that the lock is not held long, only until the end of this startup
906|	 * transaction.  This is OK since we will advertise our use of the
907|	 * database in the ProcArray before dropping the lock (in fact, that's the
908|	 * next thing to do).  Anyone trying a DROP DATABASE after this point will
909|	 * see us in the array once they have the lock.  Ordering is important for
910|	 * this because we don't want to advertise ourselves as being in this
911|	 * database until we have the lock; otherwise we create what amounts to a
912|	 * deadlock with CountOtherDBBackends().
913|	 *
914|	 * Note: use of RowExclusiveLock here is reasonable because we envision
915|	 * our session as being a concurrent writer of the database.  If we had a
916|	 * way of declaring a session as being guaranteed-read-only, we could use
917|	 * AccessShareLock for such sessions and thereby not conflict against
918|	 * CREATE DATABASE.
919|	 */
920|	if (!bootstrap)
921|		LockSharedObject(DatabaseRelationId, MyDatabaseId, 0,
922|						 RowExclusiveLock);
923|
924|	/*
925|	 * Now we can mark our PGPROC entry with the database ID.
926|	 *
927|	 * We assume this is an atomic store so no lock is needed; though actually
928|	 * things would work fine even if it weren't atomic.  Anyone searching the
929|	 * ProcArray for this database's ID should hold the database lock, so they
930|	 * would not be executing concurrently with this store.  A process looking
931|	 * for another database's ID could in theory see a chance match if it read
932|	 * a partially-updated databaseId value; but as long as all such searches
933|	 * wait and retry, as in CountOtherDBBackends(), they will certainly see
934|	 * the correct value on their next try.
935|	 */
936|	MyProc->databaseId = MyDatabaseId;
937|
938|	/*
939|	 * We established a catalog snapshot while reading pg_authid and/or
940|	 * pg_database; but until we have set up MyDatabaseId, we won't react to
941|	 * incoming sinval messages for unshared catalogs, so we won't realize it
942|	 * if the snapshot has been invalidated.  Assume it's no good anymore.
943|	 */
944|	InvalidateCatalogSnapshot();
945|
946|	/*
947|	 * Recheck pg_database to make sure the target database hasn't gone away.
948|	 * If there was a concurrent DROP DATABASE, this ensures we will die
949|	 * cleanly without creating a mess.
950|	 */
951|	if (!bootstrap)
952|	{
953|		HeapTuple	tuple;
954|
955|		tuple = GetDatabaseTuple(dbname);
956|		if (!HeapTupleIsValid(tuple) ||
957|			MyDatabaseId != ((Form_pg_database) GETSTRUCT(tuple))->oid ||
958|			MyDatabaseTableSpace != ((Form_pg_database) GETSTRUCT(tuple))->dattablespace)
959|			ereport(FATAL,
960|					(errcode(ERRCODE_UNDEFINED_DATABASE),
961|					 errmsg("database \"%s\" does not exist", dbname),
962|					 errdetail("It seems to have just been dropped or renamed.")));
963|	}
964|
965|	/*
966|	 * Now we should be able to access the database directory safely. Verify
967|	 * it's there and looks reasonable.
968|	 */
969|	fullpath = GetDatabasePath(MyDatabaseId, MyDatabaseTableSpace);
970|
971|	if (!bootstrap)
972|	{
973|		if (access(fullpath, F_OK) == -1)
974|		{
975|			if (errno == ENOENT)
976|				ereport(FATAL,
977|						(errcode(ERRCODE_UNDEFINED_DATABASE),
978|						 errmsg("database \"%s\" does not exist",
979|								dbname),
980|						 errdetail("The database subdirectory \"%s\" is missing.",
981|								   fullpath)));
982|			else
983|				ereport(FATAL,
984|						(errcode_for_file_access(),
985|						 errmsg("could not access directory \"%s\": %m",
986|								fullpath)));
987|		}
988|
989|		ValidatePgVersion(fullpath);
990|	}
991|
992|	SetDatabasePath(fullpath);
993|
994|	/*
995|	 * It's now possible to do real access to the system catalogs.
996|	 *
997|	 * Load relcache entries for the system catalogs.  This must create at
998|	 * least the minimum set of "nailed-in" cache entries.
999|	 */
1000|	RelationCacheInitializePhase3();
1001|
1002|	/* set up ACL framework (so CheckMyDatabase can check permissions) */
1003|	initialize_acl();
1004|
1005|	/*
1006|	 * Re-read the pg_database row for our database, check permissions and set
1007|	 * up database-specific GUC settings.  We can't do this until all the
1008|	 * database-access infrastructure is up.  (Also, it wants to know if the
1009|	 * user is a superuser, so the above stuff has to happen first.)
1010|	 */
1011|	if (!bootstrap)
1012|		CheckMyDatabase(dbname, am_superuser, override_allow_connections);
1013|
1014|	/*
1015|	 * Now process any command-line switches and any additional GUC variable
1016|	 * settings passed in the startup packet.   We couldn't do this before
1017|	 * because we didn't know if client is a superuser.
1018|	 */
1019|	if (MyProcPort != NULL)
1020|		process_startup_options(MyProcPort, am_superuser);
1021|
1022|	/* Process pg_db_role_setting options */
1023|	process_settings(MyDatabaseId, GetSessionUserId());
1024|
1025|	/* Apply PostAuthDelay as soon as we've read all options */
1026|	if (PostAuthDelay > 0)
1027|		pg_usleep(PostAuthDelay * 1000000L);
1028|
1029|	/*
1030|	 * Initialize various default states that can't be set up until we've
1031|	 * selected the active user and gotten the right GUC settings.
1032|	 */
1033|
1034|	/* set default namespace search path */
1035|	InitializeSearchPath();
1036|
1037|	/* initialize client encoding */
1038|	InitializeClientEncoding();
1039|
1040|	/* Initialize this backend's session state. */
1041|	InitializeSession();
1042|
1043|	/* report this backend in the PgBackendStatus array */
1044|	if (!bootstrap)
1045|		pgstat_bestart();
1046|
1047|	/* close the transaction we started above */
1048|	if (!bootstrap)
1049|		CommitTransactionCommand();
